-- Entasis Academy, migration 9 : schemas et figures des decks (brouillons).
--
-- Genere par scripts/academy/generer-decks.mjs depuis scripts/academy/decks/*.json :
-- ne pas editer a la main, regenerer. Complete le brouillon courant d un
-- module deja seme par la migration 7 : pose les schemas de la version
-- (remplacement par cle, les autres cles conservees), pose payload.figure
-- sur les exercices existants reperes par (ordre, type) qui n en ont pas
-- encore, insere les exercices nouveaux (ordre au dela du maximum existant)
-- avec leur corrige, ordre et association deja melanges. Idempotent. Une
-- version publiee n est jamais touchee : sans brouillon, raise notice et
-- rien. A appliquer apres la migration 8 (colonne academy_module_versions.schemas).

-- ── Schemas : Assurance vie : enveloppe, supports, frais, rachats et transmission (assurance-vie) ──
do $schemas_assurance_vie$
declare v_mod uuid; v_ver uuid; v_max integer; v_item uuid; v_nouveaux jsonb; v_conserves jsonb;
begin
  select id into v_mod from public.academy_modules where slug = $academy_deck$assurance-vie$academy_deck$;
  if v_mod is null then
    raise notice 'academy_9_schemas : module % absent, rien a faire (semer la migration 7 d abord)', $academy_deck$assurance-vie$academy_deck$;
    return;
  end if;
  select id into v_ver from public.academy_module_versions where module_id = v_mod and statut = 'brouillon' order by numero desc limit 1;
  if v_ver is null then
    raise notice 'academy_9_schemas : aucun brouillon pour %, rien a faire (une version publiee ne se modifie pas)', $academy_deck$assurance-vie$academy_deck$;
    return;
  end if;
  -- Schemas de la version : les cles du deck remplacent les leurs, les autres restent.
  v_nouveaux := $academy_deck$[{"cle":"enveloppe","titre":"L’enveloppe et ses deux supports","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"system-ui, -apple-system, Segoe UI, sans-serif\">\n<title>L’enveloppe et ses deux supports</title>\n<rect x=\"0\" y=\"0\" width=\"640\" height=\"360\" fill=\"#FFFFFF\"/>\n<text x=\"320\" y=\"34\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"700\" fill=\"#162443\">L’enveloppe et ses deux supports</text>\n<rect x=\"24\" y=\"54\" width=\"592\" height=\"230\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#162443\" stroke-width=\"2\"/>\n<text x=\"44\" y=\"82\" font-size=\"16\" font-weight=\"700\" fill=\"#162443\">Enveloppe : le contrat conclu avec l’assureur</text>\n<rect x=\"44\" y=\"96\" width=\"176\" height=\"26\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"132\" y=\"114\" text-anchor=\"middle\" font-size=\"14\" fill=\"#162443\">Versements</text>\n<rect x=\"232\" y=\"96\" width=\"176\" height=\"26\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"320\" y=\"114\" text-anchor=\"middle\" font-size=\"14\" fill=\"#162443\">Arbitrages</text>\n<rect x=\"420\" y=\"96\" width=\"176\" height=\"26\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"508\" y=\"114\" text-anchor=\"middle\" font-size=\"14\" fill=\"#162443\">Rachats à tout moment</text>\n<text x=\"596\" y=\"82\" text-anchor=\"end\" font-size=\"14\" fill=\"#8A95A8\">la souplesse du contrat</text>\n<rect x=\"44\" y=\"136\" width=\"264\" height=\"134\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#162443\" stroke-width=\"2\"/>\n<path d=\"M44 144 a8 8 0 0 1 8 -8 h248 a8 8 0 0 1 8 8 v24 h-264 z\" fill=\"#162443\"/>\n<text x=\"176\" y=\"158\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#FFFFFF\">Fonds en euros</text>\n<text x=\"176\" y=\"192\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#162443\">Capital garanti par l’assureur</text>\n<text x=\"176\" y=\"214\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">net des frais du contrat</text>\n<text x=\"176\" y=\"236\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Intérêts acquis chaque année</text>\n<text x=\"176\" y=\"258\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Prélèvements sociaux chaque année</text>\n<rect x=\"332\" y=\"136\" width=\"264\" height=\"134\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#162443\" stroke-width=\"2\"/>\n<path d=\"M332 144 a8 8 0 0 1 8 -8 h248 a8 8 0 0 1 8 8 v24 h-264 z\" fill=\"#C5A55A\"/>\n<text x=\"464\" y=\"158\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#162443\">Unités de compte</text>\n<text x=\"464\" y=\"192\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#162443\">Nombre de parts garanti</text>\n<text x=\"464\" y=\"214\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Valeur des parts non garantie</text>\n<text x=\"464\" y=\"236\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Risque de perte en capital</text>\n<text x=\"464\" y=\"258\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Rachat à la valeur du jour</text>\n<text x=\"320\" y=\"316\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#162443\">Disponible ne veut pas dire sans risque.</text>\n<text x=\"320\" y=\"340\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Le rendement et le risque viennent des supports, pas de l’enveloppe.</text>\n</svg>","legende":"L’enveloppe donne la souplesse, le support donne le rendement et le risque. Seul le fonds en euros garantit le capital ; les unités de compte ne garantissent qu’un nombre de parts."},{"cle":"primes_70_ans","titre":"Primes versées avant et après 70 ans","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"system-ui, -apple-system, Segoe UI, sans-serif\">\n<title>Primes versées avant et après 70 ans</title>\n<rect x=\"0\" y=\"0\" width=\"640\" height=\"360\" fill=\"#FFFFFF\"/>\n<text x=\"320\" y=\"32\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"700\" fill=\"#162443\">Primes versées avant et après 70 ans</text>\n<text x=\"40\" y=\"56\" font-size=\"13\" fill=\"#8A95A8\">Âge de l’assuré au moment du versement</text>\n<line x1=\"40\" y1=\"70\" x2=\"598\" y2=\"70\" stroke=\"#8A95A8\" stroke-width=\"2\"/>\n<polygon points=\"598,64 612,70 598,76\" fill=\"#8A95A8\"/>\n<line x1=\"320\" y1=\"84\" x2=\"320\" y2=\"310\" stroke=\"#C5A55A\" stroke-width=\"2\" stroke-dasharray=\"6 6\"/>\n<rect x=\"286\" y=\"57\" width=\"68\" height=\"26\" rx=\"8\" fill=\"#162443\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"320\" y=\"75\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\">70 ans</text>\n<text x=\"168\" y=\"108\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#162443\">Primes versées avant 70 ans</text>\n<text x=\"472\" y=\"108\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#162443\">Primes versées après 70 ans</text>\n<rect x=\"44\" y=\"122\" width=\"248\" height=\"48\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"168\" y=\"142\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#162443\">Abattement de 152 500 euros</text>\n<text x=\"168\" y=\"161\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">par bénéficiaire</text>\n<line x1=\"168\" y1=\"170\" x2=\"168\" y2=\"184\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<polygon points=\"162,183 174,183 168,191\" fill=\"#C5A55A\"/>\n<rect x=\"44\" y=\"192\" width=\"248\" height=\"48\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#162443\" stroke-width=\"2\"/>\n<text x=\"168\" y=\"212\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#162443\">puis 20 %</text>\n<text x=\"168\" y=\"231\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">jusqu’à 700 000 euros</text>\n<line x1=\"168\" y1=\"240\" x2=\"168\" y2=\"254\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<polygon points=\"162,253 174,253 168,261\" fill=\"#C5A55A\"/>\n<rect x=\"44\" y=\"262\" width=\"248\" height=\"48\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#162443\" stroke-width=\"2\"/>\n<text x=\"168\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#162443\">puis 31,25 %</text>\n<text x=\"168\" y=\"301\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">au delà de 700 000 euros</text>\n<rect x=\"348\" y=\"122\" width=\"248\" height=\"66\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"472\" y=\"142\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#162443\">Abattement de 30 500 euros</text>\n<text x=\"472\" y=\"161\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">en tout, quel que soit</text>\n<text x=\"472\" y=\"179\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">le nombre de bénéficiaires</text>\n<line x1=\"472\" y1=\"188\" x2=\"472\" y2=\"202\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<polygon points=\"466,201 478,201 472,209\" fill=\"#C5A55A\"/>\n<rect x=\"348\" y=\"210\" width=\"248\" height=\"48\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#162443\" stroke-width=\"2\"/>\n<text x=\"472\" y=\"230\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#162443\">puis droits de succession</text>\n<text x=\"472\" y=\"249\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">sur le surplus des primes</text>\n<rect x=\"24\" y=\"322\" width=\"592\" height=\"30\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"320\" y=\"342\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#162443\">Conjoint marié et partenaire de PACS : exonérés, avant comme après 70 ans.</text>\n</svg>","legende":"Avant 70 ans, chaque bénéficiaire a son abattement de 152 500 euros ; après 70 ans, un seul abattement de 30 500 euros pour tous, puis les droits de succession sur le surplus des primes. Le conjoint marié et le partenaire de PACS sont exonérés dans les deux cas."}]$academy_deck$::jsonb;
  select coalesce(jsonb_agg(s), '[]'::jsonb) into v_conserves
    from jsonb_array_elements(coalesce((select schemas from public.academy_module_versions where id = v_ver), '[]'::jsonb)) s
   where not exists (select 1 from jsonb_array_elements(v_nouveaux) x where x ->> 'cle' = s ->> 'cle');
  update public.academy_module_versions set schemas = v_conserves || v_nouveaux, updated_at = now() where id = v_ver;
  -- Figures : posee sur l exercice existant (ordre, type) qui n en a pas ; au dela du maximum, exercice nouveau.
  select coalesce(max(ordre), 0) into v_max from public.academy_items where version_id = v_ver;
  if v_max >= 7 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"enveloppe"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 7 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 7, $academy_deck$choix$academy_deck$, $academy_deck$Enveloppe et supports$academy_deck$, 2, $academy_deck${"enonce":"Cas fictif. Un client vous dit : « Avec l'assurance vie, je peux retirer quand je veux, donc je ne peux pas perdre d'argent. » Quelle réponse est juste ?","choix":["Le rachat est possible à tout moment, mais sur les unités de compte il se fait à la valeur du jour, qui peut être inférieure aux versements","C'est exact : l'assureur garantit au moins les sommes versées, quel que soit le support","C'est exact avant huit ans ; ensuite l'épargne est bloquée","Le rachat n'est possible qu'après huit ans, ce qui protège le capital"],"figure":{"ref":"enveloppe"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$Disponible ne veut pas dire sans risque : seul le fonds en euros garantit le capital.$academy_deck$);
  end if;
  if v_max >= 8 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"enveloppe"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 8 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 8, $academy_deck$choix$academy_deck$, $academy_deck$Enveloppe et supports$academy_deck$, 2, $academy_deck${"enonce":"Cas fictif. Une cliente dispose de 60 000 euros. Elle aura besoin de 20 000 euros dans dix-huit mois pour des travaux ; le reste n'a pas d'usage prévu avant dix ans. Quelle orientation retenir pour les 20 000 euros ?","choix":["Un support sans risque de perte en capital, car l'horizon est court et la somme doit être retrouvée intacte","Des unités de compte, car dix-huit mois suffisent pour absorber une baisse","La même répartition que les 40 000 euros restants, pour simplifier le contrat","Aucune décision possible : l'assurance vie bloque les fonds pendant huit ans"],"figure":{"ref":"enveloppe"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$Le support découle de l'horizon et de la part à retrouver intacte ; une somme à court terme ne s'expose pas au risque de perte.$academy_deck$);
  end if;
  if v_max >= 32 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"primes_70_ans"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 32 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 32, $academy_deck$choix$academy_deck$, $academy_deck$Fiscalité décès$academy_deck$, 2, $academy_deck${"enonce":"Cas fictif. Un client de 72 ans souhaite verser 100 000 euros sur une assurance vie au profit de ses deux enfants « pour profiter des 152 500 euros par enfant ». Que lui expliquer ?","choix":["L'abattement de 152 500 euros par bénéficiaire ne concerne que les primes versées avant 70 ans ; après 70 ans, c'est un abattement global de 30 500 euros, puis les droits de succession sur le surplus des primes","Il a raison : l'abattement de 152 500 euros s'applique quel que soit l'âge au versement","Après 70 ans, plus aucun versement n'est autorisé sur une assurance vie","Après 70 ans, le capital transmis est intégralement exonéré pour les enfants"],"figure":{"ref":"primes_70_ans"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$Le régime des capitaux décès dépend de l'âge de l'assuré au moment des versements ; après 70 ans, 30 500 euros en tout.$academy_deck$);
  end if;
  if v_max >= 41 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"enveloppe"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 41 and type = $academy_deck$multi$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 41, $academy_deck$multi$academy_deck$, $academy_deck$Enveloppe et supports$academy_deck$, 2, $academy_deck${"enonce":"Sur le schéma, cochez tout ce que l’enveloppe apporte au client, quel que soit le support choisi.","choix":["Des versements","Des arbitrages entre supports","Des rachats à tout moment","La garantie du capital investi","Un nombre de parts garanti"],"figure":{"ref":"enveloppe"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"indices":[0,1,2]}$academy_deck$::jsonb, $academy_deck$L’enveloppe donne la souplesse : versements, arbitrages, rachats ; la garantie du capital ou du nombre de parts vient du support, pas du contrat.$academy_deck$);
  end if;
  if v_max >= 42 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"primes_70_ans"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 42 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 42, $academy_deck$choix$academy_deck$, $academy_deck$Fiscalité décès$academy_deck$, 2, $academy_deck${"enonce":"Cas fictif. Un client désigne ses trois enfants comme bénéficiaires à parts égales, le contrat étant suffisamment provisionné pour que chaque abattement joue en entier. En vous appuyant sur le schéma, quel total d’abattements s’applique aux capitaux décès, selon que les primes ont été versées avant ou après ses 70 ans ?","choix":["457 500 euros si les primes ont été versées avant 70 ans, soit 152 500 euros pour chacun des trois enfants, et 30 500 euros en tout si elles l’ont été après","457 500 euros avant 70 ans et 91 500 euros après 70 ans, soit 30 500 euros pour chacun des trois enfants","152 500 euros avant 70 ans et 30 500 euros après 70 ans, chaque abattement se partageant entre les trois enfants","30 500 euros dans les deux cas, l’abattement de 152 500 euros étant réservé au conjoint marié"],"figure":{"ref":"primes_70_ans"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$Avant 70 ans, l’abattement de 152 500 euros se compte par bénéficiaire : trois enfants, trois abattements, soit 457 500 euros. Après 70 ans, 30 500 euros en tout, quel que soit le nombre de bénéficiaires et de contrats.$academy_deck$);
  end if;
  if v_max >= 43 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"primes_70_ans"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 43 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 43, $academy_deck$choix$academy_deck$, $academy_deck$Fiscalité décès$academy_deck$, 3, $academy_deck${"enonce":"Cas fictif. Un client a versé 400 000 euros avant ses 70 ans au profit d’un seul bénéficiaire, son fils, et le contrat vaut ce montant au décès. En vous appuyant sur le schéma, quelle fraction est taxée à 20 % ?","choix":["247 500 euros : ce qui dépasse l’abattement de 152 500 euros, sans atteindre le palier de 31,25 %","400 000 euros : l’abattement de 152 500 euros ne joue qu’après 70 ans","369 500 euros : ce qui dépasse l’abattement global de 30 500 euros","Aucune : un enfant est exonéré comme le conjoint"],"figure":{"ref":"primes_70_ans"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$Avant 70 ans, chaque bénéficiaire a 152 500 euros d’abattement ; 400 000 moins 152 500 = 247 500 euros à 20 %, le taux de 31,25 % ne commençant qu’au delà de 700 000 euros.$academy_deck$);
  end if;
end
$schemas_assurance_vie$;
